CREATE TABLE cities (id INT PRIMARY KEY, name VARCHAR(50), country_code CHAR(2), country VARCHAR(50), lat DOUBLE PRECISION, lon DOUBLE PRECISION);
CREATE TABLE orders (id INT PRIMARY KEY, created_at TIMESTAMP, city_id INT, category VARCHAR(20), channel VARCHAR(20), quantity INT, amount NUMERIC(10,2), customer VARCHAR(40), note TEXT);
CREATE TABLE events (id INT PRIMARY KEY, user_id INT, signup_date DATE, event_date DATE, stage VARCHAR(20));
